export default function Footer() {
  const year = new Date().getFullYear();

  const scrollTo = (e: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    e.preventDefault();
    document.querySelector(href)?.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <footer className="footer" role="contentinfo">
      <div className="container">
        <div className="footer-inner">
          {/* Brand */}
          <div>
            <div className="footer-logo">
              Tharu<span>.</span>Photography
            </div>
            <div className="footer-tagline">Capturing Life's Most Beautiful Moments</div>
          </div>

          {/* Nav Links */}
          <ul className="footer-links">
            {[
              { label: 'Home',         href: '#hero'         },
              { label: 'About',        href: '#about'        },
              { label: 'Portfolio',    href: '#gallery'      },
              { label: 'Services',     href: '#services'     },
              { label: 'Contact',      href: '#contact'      },
            ].map((link) => (
              <li key={link.href}>
                <a href={link.href} onClick={(e) => scrollTo(e, link.href)}>
                  {link.label}
                </a>
              </li>
            ))}
          </ul>
        </div>

        <div className="footer-bottom">
          <p className="footer-copy">
            © {year} Tharu Photography. All rights reserved.
          </p>
          <p className="footer-made">
            Made with <span>♥</span> in Sri Lanka
          </p>
        </div>
      </div>
    </footer>
  );
}
